/*
 * Batched (SIMD-friendly) Rys root/weight evaluation for CINTg0_1e_grids
 * ONLY (COSX's ESP-integral-over-many-grid-points kernel) - nroots=1,2,3.
 *
 * Not a modification of rys_roots.c - a NEW, separate file, so every other
 * caller of CINTrys_roots (g2e.c/RIJK, g1e.c, cint3c1e.c) is completely
 * unaffected; wired in only inside g1e_grids.c's per-grid-point loop,
 * gated to nroots<=3 (nroots>=4 falls back to the original CINTrys_roots,
 * scalar per point, as before).
 *
 * History: a cubic-spline-table (matching ORCA's own COSX paper,
 * Helmich-Paris et al. JCP 155, 104109 (2021) Supp. Mat. Sec. I)
 * implementation was tried and measured WORSE than this bucketed
 * approach, both with GCC auto-vectorization (blocked outright - "no
 * vectype for stmt", GCC won't auto-emit AVX2 gather) and with explicit
 * hand-written AVX2 gather intrinsics (still slower - x86 gather
 * instructions are a genuine, measured, hardware-level bottleneck on this
 * CPU, not a missed compiler optimization). Abandoned in favor of this
 * approach, which needs no table lookups at all.
 *
 * Same exact polynomial coefficients/formulas as rys_root1/2/3
 * (rys_roots.c, copied verbatim, not re-derived), restructured as
 * "bucket points by which x-region they fall in, then evaluate each
 * bucket with a branch-free #pragma GCC ivdep loop" instead of "branch
 * per point". Floating point result for any single point is bit-
 * identical to calling rys_root1/2/3 point-by-point (same operations,
 * same order, only WHICH points execute together changed).
 */
#include <math.h>
#include "cint_config.h"

#define PIE4 0.78539816339744827900

/* ---------------- nroots = 1 ---------------- */
void CINTrys_roots1_grids_batch(int npts, const double *X, double *roots, double *weights)
{
        int idx15[GRID_BLKSIZE], n15 = 0;
        int idx10[GRID_BLKSIZE], n10 = 0;
        int idx5[GRID_BLKSIZE], n5 = 0;
        int idx3[GRID_BLKSIZE], n3 = 0;
        int idx1[GRID_BLKSIZE], n1 = 0;
        int idx0[GRID_BLKSIZE], n0 = 0;
        int ig, k;
        double x, Y, F1, E, WW1;

        for (ig = 0; ig < npts; ig++) {
                x = X[ig];
                if (x > 33.) {
                        weights[ig] = sqrt(PIE4/x);
                        roots[ig] = 0.5E+00/(x-0.5E+00);
                } else if (x < 3.e-7) {
                        weights[ig] = 1.0E+00 - x/3.0E+00;
                        roots[ig] = 0.5E+00 - x/5.0E+00;
                } else if (x > 15.) {
                        idx15[n15++] = ig;
                } else if (x > 10.) {
                        idx10[n10++] = ig;
                } else if (x > 5.) {
                        idx5[n5++] = ig;
                } else if (x > 3.) {
                        idx3[n3++] = ig;
                } else if (x > 1.) {
                        idx1[n1++] = ig;
                } else {
                        idx0[n0++] = ig;
                }
        }

#pragma GCC ivdep
        for (k = 0; k < n15; k++) {
                ig = idx15[k]; x = X[ig]; E = exp(-x); Y = 1./x;
                F1 = ((( 1.9623264149430E-01*Y-4.9695241464490E-01)*Y -
                       6.0156581186481E-05)* E + sqrt(PIE4/x) -  E)*Y;
                F1 *= .5; WW1 = 2. * x * F1 + E;
                weights[ig] = WW1; roots[ig] = F1 / (WW1 - F1);
        }
#pragma GCC ivdep
        for (k = 0; k < n10; k++) {
                ig = idx10[k]; x = X[ig]; E = exp(-x); Y = 1./x;
                F1 = ((((-1.8784686463512E-01*Y+2.2991849164985E-01)*Y -
                        4.9893752514047E-01)*Y-2.1916512131607E-05)* E
                        + sqrt(PIE4/x) - E)*Y;
                F1 *= .5; WW1 = 2. * x * F1 + E;
                weights[ig] = WW1; roots[ig] = F1 / (WW1 - F1);
        }
#pragma GCC ivdep
        for (k = 0; k < n5; k++) {
                ig = idx5[k]; x = X[ig]; E = exp(-x); Y = 1./x;
                F1 = ((((((( 4.6897511375022E-01*Y-6.9955602298985E-01)*Y +
                           5.3689283271887E-01)*Y-3.2883030418398E-01)*Y +
                         2.4645596956002E-01)*Y-4.9984072848436E-01)*Y -
                       3.1501078774085E-06)* E + sqrt(PIE4/x) - E)*Y;
                F1 *= .5; WW1 = 2. * x * F1 + E;
                weights[ig] = WW1; roots[ig] = F1 / (WW1 - F1);
        }
#pragma GCC ivdep
        for (k = 0; k < n3; k++) {
                ig = idx3[k]; x = X[ig]; E = exp(-x); Y = x-4.0E+00;
                F1 = ((((((((((-2.62453564772299E-11*Y+3.24031041623823E-10 )*Y-
                              3.614965656163E-09)*Y+3.760256799971E-08)*Y-
                            3.553558319675E-07)*Y+3.022556449731E-06)*Y-
                          2.290098979647E-05)*Y+1.526537461148E-04)*Y-
                        8.81947375894379E-04 )*Y+4.33207949514611E-03 )*Y-
                      1.75257821619926E-02 )*Y+5.28406320615584E-02;
                WW1 = 2. * x * F1 + E;
                weights[ig] = WW1; roots[ig] = F1 / (WW1 - F1);
        }
#pragma GCC ivdep
        for (k = 0; k < n1; k++) {
                ig = idx1[k]; x = X[ig]; E = exp(-x); Y = x-2.0E+00;
                F1 = ((((((((((-1.61702782425558E-10*Y+1.96215250865776E-09 )*Y-
                              2.14234468198419E-08 )*Y+2.17216556336318E-07 )*Y-
                            1.98850171329371E-06 )*Y+1.62429321438911E-05 )*Y-
                          1.16740298039895E-04 )*Y+7.24888732052332E-04 )*Y-
                        3.79490003707156E-03 )*Y+1.61723488664661E-02 )*Y-
                      5.29428148329736E-02 )*Y+1.15702180856167E-01;
                WW1 = 2. * x * F1 + E;
                weights[ig] = WW1; roots[ig] = F1 / (WW1 - F1);
        }
#pragma GCC ivdep
        for (k = 0; k < n0; k++) {
                ig = idx0[k]; x = X[ig]; E = exp(-x);
                F1 = ((((((((-8.36313918003957E-08*x+1.21222603512827E-06 )*x-
                            1.15662609053481E-05 )*x+9.25197374512647E-05 )*x-
                          6.40994113129432E-04 )*x+3.78787044215009E-03 )*x-
                        1.85185172458485E-02 )*x+7.14285713298222E-02 )*x-
                      1.99999999997023E-01 )*x+3.33333333333318E-01;
                WW1 = 2. * x * F1 + E;
                weights[ig] = WW1; roots[ig] = F1 / (WW1 - F1);
        }
}

